  await tap('[data-part="separator"]');await tap('[data-part="engine-0"]');await tap('[data-part="small"]');assert.equal(await call('return app.getState().craft.stages[1].engine;'),0);assert(await call('return app.getState().craft.stages[0].large>=1;'));assert.equal(await call('return app.getState().craft.stages[0].engine;'),0);
